--
-- Table structure for table `crm_llamadas`
--

DROP TABLE IF EXISTS `crm_llamadas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `crm_llamadas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tipo` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `captacion` enum('INBOUND','OUTBOUND') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `canal` enum('Teléfono','Whatsapp','Email') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contacto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefono` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dni_ruc` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `propietario_id` int DEFAULT NULL,
  `departamento` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provincia` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `distrito` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `direccion` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `modelo_equipo` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serie_equipo` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `asesor_id` int NOT NULL,
  `asignado` int DEFAULT NULL,
  `comentario` text COLLATE utf8mb4_unicode_ci,
  `fecha_creacion` datetime DEFAULT CURRENT_TIMESTAMP,
  `estado` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Abierto',
  `codigo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_crm_llamadas_codigo` (`codigo`),
  KEY `idx_crm_dni_ruc` (`dni_ruc`),
  KEY `idx_crm_tipo` (`tipo`),
  KEY `idx_crm_fecha` (`fecha_creacion`),
  KEY `fk_crm_llamada_propietario` (`propietario_id`),
  KEY `fk_crm_llamada_asesor` (`asesor_id`),
  KEY `idx_crm_llamadas_asignado` (`asignado`),
  CONSTRAINT `fk_crm_llamada_asesor` FOREIGN KEY (`asesor_id`) REFERENCES `usuario` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_crm_llamada_asignado` FOREIGN KEY (`asignado`) REFERENCES `usuario` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_crm_llamada_propietario` FOREIGN KEY (`propietario_id`) REFERENCES `propietario` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

