--
-- Table structure for table `mantenimientos`
--

DROP TABLE IF EXISTS `mantenimientos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mantenimientos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tractor_id` int DEFAULT NULL,
  `requerimiento` varchar(50) NOT NULL COMMENT 'Breve descripción del motivo del mantenimiento.',
  `horometro` decimal(10,1) DEFAULT NULL,
  `OT` varchar(50) DEFAULT NULL COMMENT 'Número de Orden de Trabajo.',
  `estado` varchar(50) NOT NULL COMMENT 'Estado del mantenimiento (Ej: Pendiente, En curso, Terminado).',
  `tecnico_principal_id` int DEFAULT NULL,
  `ayudante_1_id` int DEFAULT NULL COMMENT 'ID del usuario con rol Mecánico (Ayudante 1). FK a usuario.id.',
  `ayudante_2_id` int DEFAULT NULL COMMENT 'ID del usuario con rol Mecánico (Ayudante 2). FK a usuario.id.',
  `fecha_inicio` date DEFAULT NULL,
  `fecha_fin` date DEFAULT NULL,
  `observacion_postventa` text COMMENT 'Comentarios o detalles del área de postventa.',
  `observacion_mecanico` text COMMENT 'Reporte y detalles del trabajo realizado por el equipo técnico.',
  `total_gastos` decimal(10,2) DEFAULT NULL,
  `total_viaticos` decimal(10,2) DEFAULT NULL,
  `total_gastosD` decimal(10,2) DEFAULT NULL,
  `factura` varchar(255) DEFAULT NULL,
  `moneda_factura` varchar(20) DEFAULT NULL,
  `monto_factura` decimal(10,2) DEFAULT NULL,
  `propietario_id` int DEFAULT NULL COMMENT 'ID del propietario asociado al tractor en el momento del mantenimiento (FK a propietario.id).',
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `recomendaciones` text,
  `hora_inicio` varchar(255) DEFAULT NULL,
  `hora_fin` varchar(255) DEFAULT NULL,
  `codigo_requerimiento` varchar(255) DEFAULT NULL,
  `departamento_servicio` varchar(255) DEFAULT NULL,
  `provincia_servicio` varchar(255) DEFAULT NULL,
  `distrito_servicio` varchar(255) DEFAULT NULL,
  `direccion_servicio` varchar(255) DEFAULT NULL,
  `comentario_servicio` text,
  `calificacion_servicio` varchar(255) DEFAULT NULL,
  `codigo_req` varchar(20) DEFAULT NULL,
  `cod_llamada` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `firma_ot` mediumblob,
  `activo_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UQ_mantenimientos_OT` (`OT`),
  UNIQUE KEY `UQ_mantenimientos_codigo_req` (`codigo_req`),
  KEY `fk_mantenimientos_tecnico_principal` (`tecnico_principal_id`),
  KEY `fk_mantenimientos_ayudante1` (`ayudante_1_id`),
  KEY `fk_mantenimientos_ayudante2` (`ayudante_2_id`),
  KEY `fk_mantenimientos_propietario` (`propietario_id`),
  KEY `fk_mantenimientos_tractor` (`tractor_id`),
  KEY `idx_mantenimientos_cod_llamada` (`cod_llamada`),
  KEY `idx_mantenimientos_activo_id` (`activo_id`),
  CONSTRAINT `fk_mantenimientos_activo_id` FOREIGN KEY (`activo_id`) REFERENCES `af_activos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_mantenimientos_ayudante1` FOREIGN KEY (`ayudante_1_id`) REFERENCES `usuario` (`id`),
  CONSTRAINT `fk_mantenimientos_ayudante2` FOREIGN KEY (`ayudante_2_id`) REFERENCES `usuario` (`id`),
  CONSTRAINT `fk_mantenimientos_cod_llamada` FOREIGN KEY (`cod_llamada`) REFERENCES `crm_llamadas` (`codigo`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_mantenimientos_propietario` FOREIGN KEY (`propietario_id`) REFERENCES `propietario` (`id`),
  CONSTRAINT `fk_mantenimientos_tecnico_principal` FOREIGN KEY (`tecnico_principal_id`) REFERENCES `usuario` (`id`),
  CONSTRAINT `fk_mantenimientos_tractor` FOREIGN KEY (`tractor_id`) REFERENCES `tractor` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=166 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

