  `celular` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dni_ruc` (`dni_ruc`),
  UNIQUE KEY `uq_propietario_dni_ruc` (`dni_ruc`)
